 if(path==='/api/progress'&&request.method==='PUT'){const input=await body(request),state=input?.state,serialized=JSON.stringify(state);if(!state||typeof state!=='object'||state.version!==1||serialized.length>PROGRESS_MAX_BYTES)return json({ok:false,code:serialized.length>PROGRESS_MAX_BYTES?'progress_too_large':null,error:'O progresso é grande demais para sincronizar com segurança. Exporte um backup pelo Perfil.'},413,request);const current=await env.DB.prepare('SELECT server_revision FROM user_progress WHERE user_id=?').bind(user.id).first(),base=Number(input.baseRevision)||0;if(current&&base!==current.server_revision)return json({ok:false,code:'progress_conflict',revision:current.server_revision,error:'Seu progresso mudou em outro dispositivo. Recarregue antes de salvar.'},409,request);const revision=(current?.server_revision||0)+1,clientSavedAt=Number(input.clientSavedAt)||0,t=now();await env.DB.prepare(`INSERT INTO user_progress(user_id,state_json,client_saved_at,server_revision,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET state_json=excluded.state_json,client_saved_at=excluded.client_saved_at,server_revision=excluded.server_revision,updated_at=excluded.updated_at`).bind(user.id,serialized,clientSavedAt,revision,t).run();return json({ok:true,updatedAt:t,revision},200,request);}
 if(path==='/api/avatar'&&request.method==='GET'){if(!user.avatar_key)return new Response(null,{status:404});const object=await env.AVATARS?.get(user.avatar_key);if(!object)return new Response(null,{status:404});return new Response(object.body,{headers:{'content-type':user.avatar_type,'cache-control':'private, max-age=3600','x-content-type-options':'nosniff'}});}
 if(path==='/api/avatar'&&request.method==='PUT'){if(limited(request,'avatar',12,3600e3))return json({ok:false,error:'Muitos uploads. Aguarde antes de tentar novamente.'},429,request);if(!env.AVATARS)return json({ok:false,error:'Armazenamento de imagens indisponível.'},503,request);const declared=(request.headers.get('content-type')||'').split(';')[0],size=Number(request.headers.get('content-length')||0);if(size>MAX_AVATAR_BYTES)return json({ok:false,error:'A imagem é muito grande. Escolha uma foto menor.'},413,request);const bytes=await request.arrayBuffer();if(bytes.byteLength>MAX_AVATAR_BYTES)return json({ok:false,error:'A imagem é muito grande. Escolha uma foto menor.'},413,request);const type=avatarType(bytes,declared);if(!type)return json({ok:false,error:'Escolha uma imagem JPG, PNG ou WEBP válida.'},415,request);const old=user.avatar_key,key=`avatars/${user.id}/${uuid()}`;await env.AVATARS.put(key,bytes,{httpMetadata:{contentType:type}});await env.DB.prepare('UPDATE users SET avatar_key=?,avatar_type=?,updated_at=? WHERE id=?').bind(key,type,now(),user.id).run();if(old)await env.AVATARS.delete(old);await event(env,user.id,old?'profile_photo_changed':'profile_photo_added');return json({ok:true,avatarVersion:now()},200,request);}
